import { type ClassValue, clsx } from 'clsx';
import DOMPurify from 'dompurify';

export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

/** Cria um elemento HTML com atributos e filhos. */
export function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  attrs: Record<string, string> = {},
  ...children: (string | Node)[]
): HTMLElementTagNameMap[K] {
  const element = document.createElement(tag);
  for (const [key, value] of Object.entries(attrs)) {
    element.setAttribute(key, value);
  }
  for (const child of children) {
    if (typeof child === 'string') {
      element.appendChild(document.createTextNode(child));
    } else {
      element.appendChild(child);
    }
  }
  return element;
}

/**
 * Renderiza HTML string num container, sanitizando antes via `DOMPurify.sanitize`.
 *
 * O sanitizer remove <script>, <style>, <iframe>, event handlers on*, e
 * neutraliza `href/src/action="javascript:..."`. Para HTML 100% confiável
 * (string literal estática), o overhead de re-parse é desprezível.
 */
export function renderHtml(container: Element, html: string): void {
  container.innerHTML = DOMPurify.sanitize(html);
}

/*
 * ─── Design Tokens — Source of Truth ─────────────────────────────────────────
 * ESTE arquivo é a fonte de verdade. Edite aqui.
 *
 * As 4 stacks importam via @import "@shared/tokens/tokens.css"; o registry
 * (registry/v1/init.json) embute uma cópia do conteúdo para consumo externo.
 *
 * Existiu aqui um tokens.json — espelho DTCG parcial que ninguém lia nem gerava,
 * e cujo cabeçalho ainda mandava editá-lo em vez deste arquivo. Removido em
 * 2026-08-04: espelho sem passo de build só serve para divergir em silêncio.
 *
 * figma-variables.json, ao lado, é o oposto: GERADO a partir DESTE
 * arquivo (mais motion.css e themes/*.css) por scripts/build-figma-variables.mjs,
 * para importar como variáveis no Figma. Não editar à mão — mexeu em token,
 * rode o script. `--check` falha se estiver defasado.
 */

/* Google Fonts: cada stack faz o hoist em seu próprio globals.css (React/Vue/Svelte)
 * ou via <link> em index.html / preview-head.html (Nortear). Não duplicar aqui —
 * Vite/Lightning CSS reordena e gera warning "must precede all other rules". */

/* ── Motion tokens (durações, easings, reduced-motion) ──────────────────── */
@import "./motion.css";

/* ── Light mode (default) ─────────────────────────────────────────────────── */
:root {
  --font-size: 1rem;

  /* Typography — type scale (base × ratio, em rem)
     --type-base e --type-scale são trocados pelas classes .base-tipo-* /
     .escala-* no <html> (toolbar do Storybook, como tema/densidade/fonte).
     Degraus derivados por multiplicação encadeada; tudo em rem para respeitar
     a preferência de fonte do navegador (WCAG 1.4.4).
     Default: base 1rem × Minor Third (1.200). */
  --type-base: 1rem;
  --type-scale: 1.2;

  --text-p: var(--type-base);
  --text-h4: calc(var(--text-p) * var(--type-scale));
  --text-h3: calc(var(--text-h4) * var(--type-scale));
  --text-h2: calc(var(--text-h3) * var(--type-scale));
  --text-h1: calc(var(--text-h2) * var(--type-scale));
  --text-label: calc(var(--text-p) / var(--type-scale));

  /* Typography — font family
     --font-family-active é trocado pelas classes .fonte-* no <html>.
     --font-family aponta sempre para o active para que consumidores existentes
     (componentes que usam var(--font-family)) acompanhem a troca. */
  --font-family-active: 'Inter', sans-serif;
  --font-family: var(--font-family-active);

  /* Typography — font weights */
  --font-weight-extra-bold: 800;
  --font-weight-semi-bold: 600;
  --font-weight-medium: 500;
  --font-weight-regular: 400;

  /* Typography — line heights */
  --line-height-tight: 1.2;
  --line-height-normal: 1.5;
  --line-height-relaxed: 1.75;
  --line-height-loose: 2;

  /* Typography — letter spacing */
  --letter-spacing-tight: -0.02em;
  --letter-spacing-normal: 0em;
  --letter-spacing-wide: 0.02em;

  /* Surfaces */
  --background: 0 0% 100%;
  --foreground: 0 0% 4%;
  --card: 0 0% 100%;
  --card-foreground: 0 0% 4%;
  --popover: 0 0% 100%;
  --popover-foreground: 0 0% 4%;

  /* Brand / Interactive */
  --primary: 0 0% 9%;
  --primary-foreground: 0 0% 98%;
  --secondary: 0 0% 96%;
  --secondary-foreground: 0 0% 4%;
  --muted: 0 0% 96%;
  --muted-foreground: 0 0% 40%;
  --accent: 0 0% 96%;
  --accent-foreground: 0 0% 9%;

  /* Feedback — cores com contraste WCAG 2.2 AA (≥4.5:1) para texto sobre bg colorido
     E também para text-<color> sobre bg-<color>/10 (soft variants) */
  --destructive: 0 74% 42%;
  --destructive-foreground: 0 0% 100%;
  --success: 142 85% 22%;
  --success-foreground: 0 0% 100%;
  --warning: 45 95% 36%;
  --warning-foreground: 0 0% 100%;
  --info: 221 83% 43%;
  --info-foreground: 0 0% 100%;

  /* Structure */
  --border: 0 0% 90%;
  --input: 0 0% 90%;
  --input-background: 0 0% 100%;
  --ring: 0 0% 45%;
  --ring-offset-width: 2px;
  --ring-offset-color: 0 0% 100%;

  /* Spacing base — unidade da escala abaixo: cada --spacing-{n} é n × este valor.
     Densidades em themes/densities.css sobrescrevem (condensado/confortável),
     afetando TODOS os espaçamentos proporcionalmente. */
  --spacing-base: 0.25rem; /* 4px */

  /* Spacing scale — use estes tokens nas classes .nds-* sempre que precisar de
     um valor de spacing nomeado. Acompanham a densidade automaticamente porque
     referenciam --spacing-base.

     Regra do projeto: o valor RESOLVIDO em px deve ser múltiplo ou divisor de 8.
     O sufixo do token é o multiplicador, não o px — --spacing-10 resolve 40px
     (8×5) e é válido; o que não pode existir é um px fora do grid, como 12px,
     20px, 28px ou 36px. Valor assim em CSS é bug a corrigir. */
  --spacing-0:   0;
  --spacing-px:  1px;                               /* hairline / border */
  --spacing-0-5: calc(var(--spacing-base) * 0.5);   /* 2px  — divisor de 8 (8÷4) */
  --spacing-1:   calc(var(--spacing-base) * 1);     /* 4px  — divisor de 8 (8÷2) */
  --spacing-2:   calc(var(--spacing-base) * 2);     /* 8px  — base do grid */
  --spacing-4:   calc(var(--spacing-base) * 4);     /* 16px */
  --spacing-6:   calc(var(--spacing-base) * 6);     /* 24px */
  --spacing-8:   calc(var(--spacing-base) * 8);     /* 32px */
  --spacing-10:  calc(var(--spacing-base) * 10);    /* 40px */
  --spacing-12:  calc(var(--spacing-base) * 12);    /* 48px */
  --spacing-14:  calc(var(--spacing-base) * 14);    /* 56px */
  --spacing-16:  calc(var(--spacing-base) * 16);    /* 64px */
  --spacing-20:  calc(var(--spacing-base) * 20);    /* 80px */
  --spacing-24:  calc(var(--spacing-base) * 24);    /* 96px */

  /* Elevation / Shadows */
  --elevation-sm: 0px 1px 2px 0px rgba(0, 0, 0, 0.1);
  --elevation-md: 0px 4px 6px -1px rgba(0, 0, 0, 0.1), 0px 2px 4px -1px rgba(0, 0, 0, 0.06);
  --elevation-lg: 0px 10px 15px -3px rgba(0, 0, 0, 0.1), 0px 4px 6px -2px rgba(0, 0, 0, 0.05);
  --elevation-xl: 0px 20px 25px -5px rgba(0, 0, 0, 0.1), 0px 10px 10px -5px rgba(0, 0, 0, 0.04);

  /* Charts */
  --chart-1: 199 89% 65%;
  --chart-2: 200 100% 50%;
  --chart-3: 201 98% 48%;
  --chart-4: 201 88% 43%;
  --chart-5: 210 71% 23%;

  /* Radius — derivado de um radius base:
     --radius é o tamanho base global. A escala (none/xs–xl/full) deriva dele
     por offsets aditivos; cada componente consome um token específico
     (--radius-button, --radius-card, etc.) que por default aponta para um
     degrau da escala, mas temas podem sobrescrever (ver docs/shared/themes/).

     Valor base = 0.625rem (10px). */
  --radius: 0.625rem;              /* 10px — base global */
  /* Escala derivada do base — compartilhada pelas 4 stacks */
  --radius-none: 0;                         /* cantos retos INTENCIONAIS (flush em grupos, fullscreen) */
  --radius-xs: calc(var(--radius) - 6px);   /* 4px — micro-controles (checkbox, close, handles) */
  --radius-sm: calc(var(--radius) - 4px);   /* 6px */
  --radius-md: calc(var(--radius) - 2px);   /* 8px */
  --radius-lg: var(--radius);               /* 10px */
  --radius-xl: calc(var(--radius) + 4px);   /* 14px */
  --radius-full: 9999px;                    /* pill/círculo */

  /* Tokens por componente — superfície de theming. Os DEFAULTS derivam da
     escala (aditiva), o que mantém os pares de raio aninhado válidos em
     qualquer base: card(+4px) com inset de 4px → filho = base, sempre. */
  --radius-button: var(--radius-lg);
  --radius-input: var(--radius-lg);
  --radius-alert: var(--radius-lg);
  --radius-card: var(--radius-xl);   /* 14px */
  --radius-badge: var(--radius-full); /* pill */

  /* Dimension tokens — altura default de interativos (Button, Input, Select, Toggle, Badge...)
     Consumidos pelas classes .nds-* em height/min-height; nunca hardcode o px
     no componente. --height-* para caixas retangulares, --size-* para quadradas
     (icon-only). Ver guideline 12-tokenizacao-dimensoes. */
  --height-badge: 1.25rem;    /* 20px — compacto, só para Badge */
  --height-xs: 1.5rem;        /* 24px */
  --height-sm: 1.75rem;       /* 28px */
  --height-default: 2rem;     /* 32px */
  --height-lg: 2.25rem;       /* 36px */
  --height-xl: 2.5rem;        /* 40px */

  --size-xs: 1.5rem;          /* 24px */
  --size-sm: 1.75rem;         /* 28px */
  --size-default: 2rem;       /* 32px */
  --size-lg: 2.25rem;         /* 36px */
  --size-xl: 2.5rem;          /* 40px */

  --spacing-btn-x: 0.625rem;  /* 10px */
  --spacing-btn-x-sm: 0.625rem;
  --spacing-btn-x-lg: 0.625rem;

  /* Stroke (para variantes com borda visível) */
  --border-width-default: 1px;


  /* Z-index */
  --z-dropdown: 1000;
  --z-sticky: 1020;
  --z-fixed: 1030;
  --z-modal-backdrop: 1040;
  --z-modal: 1050;
  --z-popover: 1060;
  --z-tooltip: 1070;

  /* Sidebar */
  --sidebar: 0 0% 98%;
  --sidebar-foreground: 0 0% 4%;
  --sidebar-primary: 0 0% 9%;
  --sidebar-primary-foreground: 0 0% 98%;
  --sidebar-accent: 0 0% 96%;
  --sidebar-accent-foreground: 0 0% 9%;
  --sidebar-border: 0 0% 83%;
  --sidebar-ring: 0 0% 45%;
}

/* ── Dark mode ────────────────────────────────────────────────────────────── */
.dark {
  --background: 0 0% 9%;
  --foreground: 0 0% 98%;
  --card: 0 0% 9%;
  --card-foreground: 0 0% 98%;
  --popover: 0 0% 9%;
  --popover-foreground: 0 0% 98%;
  --primary: 0 0% 98%;
  --primary-foreground: 0 0% 9%;
  --secondary: 0 0% 15%;
  --secondary-foreground: 0 0% 98%;
  --muted: 0 0% 15%;
  --muted-foreground: 0 0% 70%;
  --accent: 0 0% 15%;
  --accent-foreground: 0 0% 98%;
  --destructive: 0 85% 70%;
  --destructive-foreground: 0 0% 100%;
  --success: 142 71% 55%;
  --success-foreground: 0 0% 0%;
  --warning: 48 95% 60%;
  --warning-foreground: 0 0% 0%;
  --info: 221 83% 53%;
  --info-foreground: 0 0% 100%;
  --border: 0 0% 15%;
  --input: 0 0% 15%;
  --input-background: 0 0% 9%;
  --ring: 0 0% 45%;
  --ring-offset-color: 0 0% 9%;
  --elevation-sm: 0px 1px 2px 0px rgba(0, 0, 0, 0.3);
  --elevation-md: 0px 4px 6px -1px rgba(0, 0, 0, 0.3), 0px 2px 4px -1px rgba(0, 0, 0, 0.2);
  --elevation-lg: 0px 10px 15px -3px rgba(0, 0, 0, 0.3), 0px 4px 6px -2px rgba(0, 0, 0, 0.2);
  --elevation-xl: 0px 20px 25px -5px rgba(0, 0, 0, 0.3), 0px 10px 10px -5px rgba(0, 0, 0, 0.1);
  --sidebar: 0 0% 9%;
  --sidebar-foreground: 0 0% 98%;
  --sidebar-primary: 0 0% 98%;
  --sidebar-primary-foreground: 0 0% 9%;
  --sidebar-accent: 0 0% 15%;
  --sidebar-accent-foreground: 0 0% 98%;
  --sidebar-border: 0 0% 15%;
  --sidebar-ring: 0 0% 45%;
}

/*
 * ─── Temas de Marca ───────────────────────────────────────────────────────────
 * Default é o tema padrão (sem classe). Warm e Cold são variantes de cor.
 *
 * Todos os projetos importam via: @import "@shared/themes/index.css"
 */
@import "./default.css";
@import "./warm.css";
@import "./cold.css";
@import "./densities.css";
@import "./fonts.css";
@import "./typescale.css";

/*
 * ─── Tema: Default ────────────────────────────────────────────────────────────
 * Tema base do sistema. Vibe: moderno, compacto, cantos suaves, densidade média-alta.
 *
 * Radius: base 10px; componentes derivam da escala:
 *   button/input/alert: lg (=base), card: xl (+4px), badge: full (pill)
 *
 * Os valores em :root (tokens.css) refletem Default. Este arquivo RE-DECLARA
 * os mesmos tokens dentro de `.tema-default` para garantir que, ao voltar de
 * `.tema-warm` ou `.tema-cold` no preview do Storybook, o cascade do CSS reverta
 * corretamente (sem essa re-declaração, browsers podem manter estado computado
 * mesmo após a remoção da classe override).
 *
 * Base Color: Neutral · Theme Color: Neutral · Chart Color: Neutral
 */
.tema-default {
  --background: 0 0% 100%;
  --foreground: 0 0% 4%;
  --card: 0 0% 100%;
  --card-foreground: 0 0% 4%;
  --popover: 0 0% 100%;
  --popover-foreground: 0 0% 4%;

  --primary: 0 0% 9%;
  --primary-foreground: 0 0% 98%;
  --secondary: 0 0% 96%;
  --secondary-foreground: 0 0% 4%;
  --muted: 0 0% 96%;
  --muted-foreground: 0 0% 40%;
  --accent: 0 0% 96%;
  --accent-foreground: 0 0% 9%;

  --destructive: 0 74% 42%;
  --destructive-foreground: 0 0% 100%;
  --success: 142 85% 22%;
  --success-foreground: 0 0% 100%;
  --warning: 45 95% 36%;
  --warning-foreground: 0 0% 100%;
  --info: 221 83% 43%;
  --info-foreground: 0 0% 100%;

  --border: 0 0% 90%;
  --input: 0 0% 90%;
  --input-background: 0 0% 100%;
  --ring: 0 0% 45%;
  --ring-offset-color: 0 0% 100%;

  /* Chart — sem variante dark (mesma paleta nos dois modos, como em warm/cold) */
  --chart-1: 199 89% 65%;
  --chart-2: 200 100% 50%;
  --chart-3: 201 98% 48%;
  --chart-4: 201 88% 43%;
  --chart-5: 210 71% 23%;

  --sidebar: 0 0% 98%;
  --sidebar-foreground: 0 0% 4%;
  --sidebar-primary: 0 0% 9%;
  --sidebar-primary-foreground: 0 0% 98%;
  --sidebar-accent: 0 0% 96%;
  --sidebar-accent-foreground: 0 0% 9%;
  --sidebar-border: 0 0% 83%;
  --sidebar-ring: 0 0% 45%;

  /* Radius — contrato de tema: temas podem sobrescrever --radius e os tokens
     por componente abaixo (identidade de forma). A escala --radius-xs..xl é
     geometria do raio aninhado e NUNCA é sobrescrita por tema. */
  --radius: 0.625rem;
  --radius-button: var(--radius-lg);
  --radius-input: var(--radius-lg);
  --radius-alert: var(--radius-lg);
  --radius-card: var(--radius-xl);
  --radius-badge: var(--radius-full);
}

/* Dark mode — combina `.dark.tema-default`. Espelha o `.dark` de tokens.css
   (mesmos valores; divergir aqui criaria dois darks "Default" diferentes). */
.dark.tema-default {
  --background: 0 0% 9%;
  --foreground: 0 0% 98%;
  --card: 0 0% 9%;
  --card-foreground: 0 0% 98%;
  --popover: 0 0% 9%;
  --popover-foreground: 0 0% 98%;

  --primary: 0 0% 98%;
  --primary-foreground: 0 0% 9%;
  --secondary: 0 0% 15%;
  --secondary-foreground: 0 0% 98%;
  --muted: 0 0% 15%;
  --muted-foreground: 0 0% 70%;
  --accent: 0 0% 15%;
  --accent-foreground: 0 0% 98%;

  --destructive: 0 85% 70%;
  --destructive-foreground: 0 0% 100%;
  --success: 142 71% 55%;
  --success-foreground: 0 0% 0%;
  --warning: 48 95% 60%;
  --warning-foreground: 0 0% 0%;
  --info: 221 83% 53%;
  --info-foreground: 0 0% 100%;

  --border: 0 0% 15%;
  --input: 0 0% 15%;
  --input-background: 0 0% 9%;
  --ring: 0 0% 45%;
  --ring-offset-color: 0 0% 9%;

  --sidebar: 0 0% 9%;
  --sidebar-foreground: 0 0% 98%;
  --sidebar-primary: 0 0% 98%;
  --sidebar-primary-foreground: 0 0% 9%;
  --sidebar-accent: 0 0% 15%;
  --sidebar-accent-foreground: 0 0% 98%;
  --sidebar-border: 0 0% 15%;
  --sidebar-ring: 0 0% 45%;
}

/*
 * ─── Tema: Warm ───────────────────────────────────────────────────────────────
 * Variante de cores quentes do tema Default.
 *
 * Estratégia:
 *   - Neutros (background, foreground, primary, secondary, muted, accent, border)
 *     ganham tint âmbar/marrom sutil (matiz ~30°, saturação 8–15%) — continuam
 *     "quase cinzas", mas a tela tem temperatura quente.
 *   - Feedback colors (destructive/success/warning/info) deslocam suavemente
 *     para o lado quente do espectro mantendo contraste WCAG AA.
 *   - Charts trocam paleta azul por paleta âmbar/laranja.
 *   - Radius, dimensões e shadows herdam de tokens.css (Default).
 *
 * Aplicado via classe `.tema-warm` no <html>. Dark mode combina com `.dark`.
 */

.tema-warm {
  /* Surfaces — tint âmbar muito sutil */
  --background: 30 25% 99%;
  --foreground: 25 20% 8%;
  --card: 30 25% 99%;
  --card-foreground: 25 20% 8%;
  --popover: 30 25% 99%;
  --popover-foreground: 25 20% 8%;

  /* Brand / Interactive — primary terracota saturado; secondary/accent creme âmbar */
  --primary: 18 75% 35%;            /* terracota / laranja queimado */
  --primary-foreground: 30 30% 98%;
  --secondary: 35 55% 92%;          /* creme âmbar claro */
  --secondary-foreground: 18 60% 22%;
  --muted: 30 20% 95%;
  --muted-foreground: 25 12% 42%;
  --accent: 35 55% 92%;             /* espelha secondary */
  --accent-foreground: 18 60% 22%;

  /* Feedback — paleta quente */
  --destructive: 0 74% 42%;
  --destructive-foreground: 0 0% 100%;
  --success: 130 60% 28%;
  --success-foreground: 0 0% 100%;
  --warning: 28 95% 38%;
  --warning-foreground: 0 0% 100%;
  --info: 24 85% 45%;
  --info-foreground: 0 0% 100%;

  /* Structure */
  --border: 30 15% 88%;
  --input: 30 15% 88%;
  --input-background: 30 25% 99%;
  --ring: 18 75% 45%;               /* alinhado com primary */
  --ring-offset-color: 30 25% 99%;

  /* Charts — paleta âmbar/laranja */
  --chart-1: 32 95% 60%;
  --chart-2: 24 90% 50%;
  --chart-3: 18 85% 45%;
  --chart-4: 36 75% 55%;
  --chart-5: 14 70% 40%;

  /* Sidebar — tint quente */
  --sidebar: 30 25% 98%;
  --sidebar-foreground: 25 20% 8%;
  --sidebar-primary: 18 75% 35%;
  --sidebar-primary-foreground: 30 30% 98%;
  --sidebar-accent: 35 55% 92%;
  --sidebar-accent-foreground: 18 60% 22%;
  --sidebar-border: 30 15% 85%;
  --sidebar-ring: 18 75% 45%;

  /* Radius — este tema PODE sobrescrever --radius e os tokens por componente
     (--radius-button/card/badge/input/alert) para mudar a identidade de forma.
     A escala --radius-xs..xl (raio aninhado) nunca é sobrescrita. */
}

/* Dark mode — combina `.dark.tema-warm` */
.dark.tema-warm {
  --background: 25 15% 9%;
  --foreground: 30 20% 96%;
  --card: 25 15% 9%;
  --card-foreground: 30 20% 96%;
  --popover: 25 15% 9%;
  --popover-foreground: 30 20% 96%;
  --primary: 22 85% 60%;            /* laranja vibrante no dark */
  --primary-foreground: 25 30% 10%;
  --secondary: 25 20% 18%;          /* marrom escuro saturado */
  --secondary-foreground: 35 55% 90%;
  --muted: 25 10% 16%;
  --muted-foreground: 30 12% 70%;
  --accent: 25 20% 18%;
  --accent-foreground: 35 55% 90%;
  --destructive: 0 80% 65%;
  --destructive-foreground: 0 0% 100%;
  --success: 130 60% 55%;
  --success-foreground: 0 0% 0%;
  --warning: 35 92% 55%;
  --warning-foreground: 0 0% 0%;
  --info: 24 85% 58%;
  --info-foreground: 0 0% 100%;
  --border: 25 10% 16%;
  --input: 25 10% 16%;
  --input-background: 25 15% 9%;
  --ring: 22 85% 55%;
  --ring-offset-color: 25 15% 9%;
  --sidebar: 25 15% 9%;
  --sidebar-foreground: 30 20% 96%;
  --sidebar-primary: 22 85% 60%;
  --sidebar-primary-foreground: 25 30% 10%;
  --sidebar-accent: 25 20% 18%;
  --sidebar-accent-foreground: 35 55% 90%;
  --sidebar-border: 25 10% 16%;
  --sidebar-ring: 22 85% 55%;
}

/*
 * ─── Tema: Cold ───────────────────────────────────────────────────────────────
 * Variante de cores frias do tema Default.
 *
 * Estratégia:
 *   - Neutros (background, foreground, primary, secondary, muted, accent, border)
 *     ganham tint azul/cyan sutil (matiz ~210°, saturação 8–15%) — continuam
 *     "quase cinzas", mas a tela tem temperatura fria.
 *   - Feedback colors (destructive/success/warning/info) deslocam suavemente
 *     para o lado frio do espectro mantendo contraste WCAG AA.
 *   - Charts trocam paleta padrão por azul/cyan/teal.
 *   - Radius, dimensões e shadows herdam de tokens.css (Default).
 *
 * Aplicado via classe `.tema-cold` no <html>. Dark mode combina com `.dark`.
 */

.tema-cold {
  /* Surfaces — tint azul muito sutil */
  --background: 210 30% 99%;
  --foreground: 215 25% 8%;
  --card: 210 30% 99%;
  --card-foreground: 215 25% 8%;
  --popover: 210 30% 99%;
  --popover-foreground: 215 25% 8%;

  /* Brand / Interactive — primary azul royal saturado; secondary/accent azul-gelo */
  --primary: 215 80% 38%;           /* azul royal */
  --primary-foreground: 210 30% 98%;
  --secondary: 205 55% 92%;         /* azul-gelo claro */
  --secondary-foreground: 215 70% 25%;
  --muted: 210 20% 95%;
  --muted-foreground: 215 12% 42%;
  --accent: 205 55% 92%;            /* espelha secondary */
  --accent-foreground: 215 70% 25%;

  /* Feedback — paleta fria */
  --destructive: 350 75% 42%;
  --destructive-foreground: 0 0% 100%;
  --success: 165 75% 26%;
  --success-foreground: 0 0% 100%;
  --warning: 200 95% 35%;
  --warning-foreground: 0 0% 100%;
  --info: 215 85% 45%;
  --info-foreground: 0 0% 100%;

  /* Structure */
  --border: 210 18% 88%;
  --input: 210 18% 88%;
  --input-background: 210 30% 99%;
  --ring: 215 80% 48%;              /* alinhado com primary */
  --ring-offset-color: 210 30% 99%;

  /* Charts — paleta azul/cyan/teal */
  --chart-1: 210 90% 60%;
  --chart-2: 195 85% 50%;
  --chart-3: 180 75% 40%;
  --chart-4: 225 80% 55%;
  --chart-5: 240 70% 45%;

  /* Sidebar — tint frio */
  --sidebar: 210 30% 98%;
  --sidebar-foreground: 215 25% 8%;
  --sidebar-primary: 215 80% 38%;
  --sidebar-primary-foreground: 210 30% 98%;
  --sidebar-accent: 205 55% 92%;
  --sidebar-accent-foreground: 215 70% 25%;
  --sidebar-border: 210 18% 85%;
  --sidebar-ring: 215 80% 48%;

  /* Radius — este tema PODE sobrescrever --radius e os tokens por componente
     (--radius-button/card/badge/input/alert) para mudar a identidade de forma.
     A escala --radius-xs..xl (raio aninhado) nunca é sobrescrita. */
}

/* Dark mode — combina `.dark.tema-cold` */
.dark.tema-cold {
  --background: 215 25% 9%;
  --foreground: 210 25% 96%;
  --card: 215 25% 9%;
  --card-foreground: 210 25% 96%;
